        original_errors = _l(attempt.get("normalization_errors")) + _l(_d(attempt.get("validation")).get("errors")); original_codes = _error_codes(original_errors); adjudicated_codes = _error_codes(errors)
        removed_codes = {code: original_codes.count(code) - adjudicated_codes.count(code) for code in sorted(set(original_codes)) if original_codes.count(code) > adjudicated_codes.count(code)}
        signal, signal_input_type = directing_signal(canonical or candidate, qa)
        scenes.append({"scene": {"scene_id": runtime["scene_id"], "book_id": inputs["scene"].get("book_id"), "episode": inputs["scene"].get("episode"), "name": inputs["scene"].get("name")}, "original_protocol_status":"PROTOCOL_INVALID", "adjudicated_protocol_status":"PROTOCOL_VALID" if validation.get("valid") else "PROTOCOL_INVALID", "original_error_codes": original_codes, "adjudicated_error_codes": adjudicated_codes, "errors_removed_by_contract_wiring": removed_codes, "errors_remaining": errors, "resolution_reason":"RUNTIME_CONTRACT_NOW_MATCHES_PROVIDER_CONTRACT", "raw_output_fingerprint": raw_hash, "raw_output_length": len(raw), "original_request_fingerprint": attempt.get("prompt_request_fingerprint"), "original_system_prompt_fingerprint": attempt.get("system_prompt_fingerprint"), "original_semantic_spec_fingerprint": attempt.get("semantic_spec_fingerprint"), "normalized_ir": normalized.get("ir"), "canonical": canonical, "epistemic": {"model_created_source_fact":False, "fact_authority_violation":sum(1 for e in errors if _d(e).get("code")=="FACT_AUTHORITY_VIOLATION"), "inference_promoted_to_fact":sum(1 for e in errors if _d(e).get("code")=="INFERENCE_PROMOTED_TO_FACT"), "unsupported_inference":sum(1 for e in errors if _d(e).get("code")=="UNSUPPORTED_INFERENCE"), "future_reveal":sum(1 for e in errors if _d(e).get("code")=="FUTURE_REVEAL"), "future_hint":sum(1 for e in errors if _d(e).get("code")=="FUTURE_HINT_EVIDENCE"), "future_support_evidence":sum(1 for e in errors if _d(e).get("code")=="FUTURE_SUPPORT_EVIDENCE")}, "directing_signal": signal, "signal_input_type": signal_input_type, "directing_result": qa})
