    canonical = [s["canonical"] for s in scenes if isinstance(s.get("canonical"), dict)]; distinct = compare_canonical_strategies(canonical, expected_scene_count=3) if canonical else {"canonical_scene_count":0,"expected_pair_count":3,"pair_count":0,"all_pairs_checked":False,"hard_failure":False,"status":"DISTINCTIVENESS_NOT_EVALUATED"}
    hard_epistemic = any(s["epistemic"][key] for s in scenes for key in ("fact_authority_violation", "inference_promoted_to_fact"))
    status = "DIRECTOR_V3_FINAL_RECANARY_ADJUDICATION_PASSED" if len(canonical)==3 and not hard_epistemic and distinct.get("all_pairs_checked") and not distinct.get("hard_failure") else "DIRECTOR_V3_FINAL_RECANARY_ADJUDICATION_FAILED"
